// Kahn 拓撲排序：能全部取出代表沒有環
// 時間複雜度: O(V + E)，空間複雜度: O(V + E)
bool canFinish(int numCourses, int** prerequisites, int prerequisitesSize,
               int* prerequisitesColSize) {
    // 用「前向星」存圖：head[u] 指向 u 的第一條邊
    int* head = malloc(sizeof(int) * numCourses);
    int* nxt = malloc(sizeof(int) * (prerequisitesSize + 1));
    int* to = malloc(sizeof(int) * (prerequisitesSize + 1));
    int* indeg = calloc(numCourses, sizeof(int));
    for (int i = 0; i < numCourses; i++) head[i] = -1;

    for (int e = 0; e < prerequisitesSize; e++) {
        int course = prerequisites[e][0], pre = prerequisites[e][1];
        to[e] = course;
        nxt[e] = head[pre];
        head[pre] = e;
        indeg[course]++;
    }

    int* queue = malloc(sizeof(int) * numCourses);
    int qh = 0, qt = 0;
    for (int i = 0; i < numCourses; i++) if (indeg[i] == 0) queue[qt++] = i;
    while (qh < qt) {
        int cur = queue[qh++];
        for (int e = head[cur]; e != -1; e = nxt[e]) {
            if (--indeg[to[e]] == 0) queue[qt++] = to[e];
        }
    }

    free(head); free(nxt); free(to); free(indeg); free(queue);
    return qt == numCourses;
}
